func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        var result = aDict
        for (k, v) in bDict {
            if let existing = result[k] {
                result[k] = deepMerge(existing, v)
            } else {
                result[k] = v
            }
        }
        return result
    }
    if let aArray = a as? [Any], let bArray = b as? [Any] {
        var result = aArray
        for item in bArray {
