import Foundation

func canonicalKey(_ value: Any) -> String {
    if let dict = value as? [String: Any] {
        if let data = try? JSONSerialization.data(withJSONObject: dict, options: .sortedKeys) {
            return data.base64EncodedString()
        }
    }
    if let array = value as? [Any] {
        if let data = try? JSONSerialization.data(withJSONObject: array, options: .sortedKeys) {
            return data.base64EncodedString()
        }
    }
    let wrapper: [Any] = [value]
    if let data = try? JSONSerialization.data(withJSONObject: wrapper, options: .sortedKeys) {
        return data.base64EncodedString()
