import Foundation

func formatStringWithCommas(_ str: String) -> String {
    let sign = str.hasPrefix("-") ? "-" : ""
    let absStr = sign == "-" ? String(str.dropFirst()) : str
    let chars = Array(absStr)
    var reversedChars: [Character] = []
    for i in stride(from: chars.count - 1, through: 0, by: -1) {
        reversedChars.append(chars[i])
    }
    var grouped = ""
    var groupCount = 0
    for (i, char) in reversedChars.enumerated() {
        grouped.append(char)
        groupCount += 1
        if groupCount % 3 == 0 && i < reversedChars.count - 1 {
            grouped.append(",")
        }
    }
    let reversedStr = String(grouped.reversed())
    return sign + reversedStr
}

func formatIntWithCommas(_ value: Int) -> String {
    return formatStringWithCommas(String(value))
}

func formatWithCommas(_ value: Double, decimals: Int = 2) -> String {
    let formatted = String(format: "%.*f", decimals, value)
    let parts = formatted.split(separator: ".")
    let intPart = String(parts[0])
    let decPart = parts.count > 1 ? String(parts[1]) : String(repeating: "0", count: decimals)
    let sign = intPart.hasPrefix("-") ? "-" : ""
    let absInt = sign == "-" ? String(intPart.dropFirst()) : intPart
    let groupedInt = formatStringWithCommas(absInt)
    return sign + groupedInt + "." + decPart
}

