func parseLine(_ line: String) -> (String, String, String, String)? {
    var l = line.trimmingCharacters(in: .whitespacesAndNewlines)
    guard l.hasPrefix("[") else { return nil }
    guard let closeBracket = l.firstIndex(of: "]") else { return nil }
    let timestamp = String(l[l.startIndex..<closeBracket])
    let afterBracket = String(l[l.index(after: closeBracket)...]).trimmingCharacters(in: .whitespaces)
    guard let openParen = afterBracket.firstIndex(of: "(") else { return nil }
    let levelName = String(afterBracket[..<openParen]).trimmingCharacters(in: .whitespaces)
    guard let closeParenRange = afterBracket.range(of: ")") else { return nil }
    let componentStart = afterBracket.index(after: openParen)
    let component = String(afterBracket[componentStart..<closeParenRange.lowerBound]).trimmingCharacters(in: .whitespaces)
    let messageStart = closeParenRange.upperBound
    var message = String(afterBracket[messageStart...]).trimmingCharacters(in: .whitespaces)
    if let dash = message.firstIndex(of: "-") {
        message = String(message[message.index(after: dash)...]).trimmingCharacters(in: .whitespaces)
    }
    let timeComponents = timestamp.split(separator: " ")
    if timeComponents.count >= 2 {
        let hourStr = String(timeComponents[1].prefix(2))
        let hourInt = Int(hourStr) ?? 0
        let hourKey = String(format: "%02d:00", hourInt)
        return (levelName, component, message, hourKey)
    }
    return (levelName, component, message, "00:00")
}

