var adj: [String: [(String, Int)]] = [:]
for edge in edges {
    let from = edge["from"] as? String ?? ""
    let to = edge["to"] as? String ?? ""
    let weight = (edge["weight"] as? NSNumber)?.intValue ?? 0
    if let neighbors = adj[from] {
        neighbors.append((to, weight))
    } else {
        adj[from] = [(to, weight)]
    }
    if let neighbors = adj[to] {
        neighbors.append((from, weight))
    } else {
        adj[to] = [(from, weight)]
    }
