const fs = require("fs");

interface Edge {
  from: string;
  to: string;
  weight: number;
}

const raw = fs.readFileSync("__FIXTURE_DIR__/graph.json", "utf8");
const data = JSON.parse(raw);
const nodes: string[] = data.nodes;
const edges: Edge[] = data.edges;

const adj: { [key: string]: { to: string; weight: number }[] } = {};
for (let i = 0; i < nodes.length; i++) {
  adj[nodes[i]] = [];
}
for (let i = 0; i < edges.length; i++) {
  const e = edges[i];
  if (!adj[e.from]) adj[e.from] = [];
  if (!adj[e.to]) adj[e.to] = [];
  adj[e.from].push({ to: e.to, weight: e.weight });
  adj[e.to].push({ to: e.from, weight: e.weight });
}

const distances: { [key: string]: number } = {};
const visited: { [key: string]: boolean } = {};
distances["A"] = 0;

while (true) {
  let current: string | null = null;
  let minDist = Infinity;
  for (let i = 0; i < nodes.length; i++) {
    const n = nodes[i];
    if (!visited[n] && distances[n] !== undefined) {
      const d = distances[n];
      if (d < minDist) {
        minDist = d;
        current = n;
      }
    }
  }
  if (current === null) break;
  visited[current] = true;
  const currentDist = distances[current];
  const neighbors = adj[current] || [];
  for (let j = 0; j < neighbors.length; j++) {
    const edge = neighbors[j];
    const newDist = currentDist + edge.weight;
    if (distances[edge.to] === undefined || newDist < distances[edge.to]) {
      distances[edge.to] = newDist;
    }
  }
}

const sortedNodes = nodes.slice().sort();
let output = "=== Shortest Paths from A ===\n\n";
for (let i = 0; i < sortedNodes.length; i++) {
  const n = sortedNodes[i];
  const d = distances[n];
  const dist = d === undefined ? Infinity : d;
  output += "A -> " + n + ": distance   " + dist + "\n";
}
fs.writeSync(1, output);

