        }
        process.waitFor();
        return stripTrailing(output.toString());
    }

    private static String stripTrailing(String s) {
        int len = s.length();
        while (len > 0 && Character.isWhitespace(s.charAt(len - 1))) {
            len--;
        }
        return s.substring(0, len);
    }

