static char* read_all(const char* cmd, size_t* len) {
    FILE* fp = popen(cmd, "r");
    if (!fp) { return NULL; }
    size_t cap = 256;
    size_t l = 0;
    char* buf = (char*)malloc(cap);
    if (!buf) { pclose(fp); return NULL; }
    int c;
    while ((c = fgetc(fp)) != EOF) {
        if (l + 2 > cap) {
            cap *= 2;
            char* tmp = (char*)realloc(buf, cap);
            if (!tmp) { free(buf); pclose(fp); return NULL; }
            buf = tmp;
        }
        buf[l++] = (char)c;
    }
    buf[l] = '\0';
    pclose(fp);
    *len = l;
    return buf;
}

static void strip_trailing_ws(char* str) {
    size_t len = strlen(str);
    while (len > 0 && isspace((unsigned char)str[len - 1])) {
        str[--len] = '\0';
    }
}

int main(void) {
    size_t len1, len2, len3, len4;
    char* hostname = read_all("hostname", &len1);
    char* os = read_all("uname -s", &len2);
    char* architecture = read_all("uname -m", &len3);
    char* username = read_all("whoami", &len4);

    strip_trailing_ws(hostname);
    strip_trailing_ws(os);
    strip_trailing_ws(architecture);
    strip_trailing_ws(username);

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", architecture);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    free(hostname);
    free(os);
    free(architecture);
    free(username);
    return 0;
}

