function determinant(matrix: number[][]): number {
  const n = matrix.length;
  if (n === 1) return matrix[0][0];
  if (n === 2) return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
  let det = 0;
  for (let j = 0; j < n; j++) {
    const minor: number[][] = [];
    for (let i = 1; i < n; i++) {
      const row: number[] = [];
      for (let k = 0; k < n; k++) {
        if (k === j) continue;
        row.push(matrix[i][k]);
      }
      minor.push(row);
    }
    det += (j % 2 === 0 ? 1 : -1) * matrix[0][j] * determinant(minor);
  }
  return det;
}

