func determinant(_ m: [[Int]]) -> Int {
    let n = m.count
    if n == 1 { return m[0][0] }
    if n == 2 { return m[0][0]*m[1][1] - m[0][1]*m[1][0] }
    var det = 0
    for col in 0..<n {
        var minor: [[Int]] = []
        for i in 1..<n {
            var row = [Int]()
            for j in 0..<n {
                if j != col { row.append(m[i][j]) }
            }
            minor.append(row)
        }
        let sign = (col % 2 == 0) ? 1 : -1
        det += sign * m[0][col] * determinant(minor)
    }
    return det
}

func formatValue(_ v: Int) -> String {
    let s = "\(v)"
    let need = 4 - s.count
    if need > 0 {
        return String(repeating: " ", count: need) + s
    } else {
        return s
    }
}

func formatRow(_ row: [Int]) -> String {
    let fields = row.map { formatValue($0) }
    return "  " + fields.joined(separator: " ")
}

