fn multiply(a: &[[i32; 3]; 3], b: &[[i32; 3]; 3]) -> [[i32; 3]; 3] {
    let mut c = [[0; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            let mut sum = 0;
            for k in 0..3 {
                sum += a[i][k] * b[k][j];
            }
            c[i][j] = sum;
        }
    }
    c
}

fn determinant(c: &[[i32; 3]; 3]) -> i32 {
    let a = c[0][0];
    let b = c[0][1];
    let c_ = c[0][2];
    let d = c[1][0];
    let e = c[1][1];
    let f = c[1][2];
    let g = c[2][0];
    let h = c[2][1];
    let i = c[2][2];
    a * (e * i - f * h) - b * (d * i - f * g) + c_ * (d * h - e * g)
}

